import { useEffect, useMemo, useRef, useState } from 'react';
import {
  DRILL_SIZE,
  cleanLabel,
  drillOrder,
  exampleWith,
  gradeDictation,
  seededRng,
  ttsLocaleOf,
} from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { ModeScreen, ModeSummary } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { drillWords } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import styles from '../Modes.module.css';

/**
 * Dictation: the device reads one of the learner's words aloud in the
 * notebook's language, and they type it. Graded with their own typing
 * strictness (Settings → Practice), like a spelling card.
 *
 * It counts for the schedule like spelling (card type dictation, source
 * session): due words come first, and a right answer to a word that is not
 * due follows the notebook's extra-practice rule.
 */
export function Dictation({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('dictation');
  const words = useMemo(
    () =>
      drillOrder(drillWords('dictation', view.words, lang), view.today, seededRng(run.seed)).slice(
        0,
        DRILL_SIZE,
      ),
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [run.seed],
  );
  const [index, setIndex] = useState(0);
  const [typed, setTyped] = useState('');
  const [outcome, setOutcome] = useState<'correct' | 'wrong' | undefined>(undefined);
  const input = useRef<HTMLInputElement>(null);
  const shownAt = useRef(0);
  const word = words[index];
  const locale = ttsLocaleOf(lang);

  const say = (text: string): void => {
    platform.tts.speak(text, locale);
  };

  // Each word is read out as it arrives; the button reads it again.
  useEffect(() => {
    if (word === undefined) return;
    say(cleanLabel(word.headword) || word.headword);
    shownAt.current = Date.now();
    input.current?.focus();
    // Once per word.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [word?.id, run.seed]);

  useEffect(
    () => () => {
      platform.tts.cancel();
    },
    [],
  );

  if (word === undefined) {
    return (
      <ModeSummary
        title={t('modes.dictation')}
        lang={lang}
        score={t('modes.scoreOf', {
          right: run.answers.filter((a) => a.correct).length,
          total: run.answers.length,
        })}
        lines={missedWords(run.answers).length === 0 && run.answers.length > 0 ? [t('modes.allRight')] : []}
        missed={missedWords(run.answers)}
        onAgain={() => {
          run.restart();
          setIndex(0);
          setTyped('');
          setOutcome(undefined);
        }}
      />
    );
  }

  const check = (): void => {
    if (outcome !== undefined || typed.trim() === '') return;
    const correct = gradeDictation(typed, word.headword, view.typedGrading);
    setOutcome(correct ? 'correct' : 'wrong');
    void run.record({
      wordId: word.id,
      headword: word.headword,
      correct,
      typed,
      latencyMs: Date.now() - shownAt.current,
    });
  };

  const next = (): void => {
    setTyped('');
    setOutcome(undefined);
    setIndex(index + 1);
  };

  const sentence = exampleWith(word);
  return (
    <ModeScreen
      title={t('modes.dictation')}
      ask={t('modes.dictationAsk')}
      counts
      progress={{ done: index, total: words.length }}
      said={
        outcome === 'correct'
          ? t('session.correct')
          : outcome === 'wrong'
            ? `${t('modes.itWas')} ${word.headword}`
            : ''
      }
      actions={
        outcome === undefined ? (
          <button type="button" className={styles.primary} disabled={typed.trim() === ''} onClick={check}>
            {t('modes.check')}
          </button>
        ) : (
          <button type="button" className={styles.primary} onClick={next}>
            {t('modes.next')}
          </button>
        )
      }
    >
      <div className={styles.prompt}>
        <div className={styles.speakers}>
          <button
            type="button"
            className={styles.speakBig}
            onClick={() => {
              say(cleanLabel(word.headword) || word.headword);
              input.current?.focus();
            }}
          >
            <Icon name="speaker" size={22} weight={1.9} />
            {t('modes.play')}
          </button>
          {sentence !== undefined && (
            <button
              type="button"
              className={styles.speak}
              onClick={() => {
                say(sentence);
                input.current?.focus();
              }}
            >
              <Icon name="headphones" size={18} weight={1.9} />
              {t('modes.playSentence')}
            </button>
          )}
        </div>
      </div>
      <input
        ref={input}
        className={cx(
          styles.input,
          outcome === 'correct' && styles.inputRight,
          outcome === 'wrong' && styles.inputWrong,
        )}
        value={typed}
        lang={lang}
        dir="auto"
        placeholder={t('modes.typeHere')}
        aria-label={t('session.typePrompt', { language: LANGUAGE_NAMES[lang] })}
        autoComplete="off"
        autoCorrect="off"
        autoCapitalize="off"
        spellCheck={false}
        readOnly={outcome !== undefined}
        onChange={(event) => {
          setTyped(event.target.value);
        }}
        onKeyDown={(event) => {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          if (outcome === undefined) check();
          else next();
        }}
      />
      {outcome !== undefined && (
        <div className={styles.reveal}>
          <span className={styles.revealLabel}>{t('modes.itWas')}</span>
          <span className={styles.revealWord}>
            <Bilingual lang={lang}>{word.headword}</Bilingual>
          </span>
          {word.meaning !== '' && (
            <span className={styles.promptSub}>
              <Bilingual lang={meaningLang}>{word.meaning}</Bilingual>
            </span>
          )}
        </div>
      )}
    </ModeScreen>
  );
}
